  "保留弹性，防止官场整体反噬。": "Retain flexibility to prevent backlash from the officialdom as a whole.",
  "保留多头并行视角，说明“子空间分工”的设计动机": "Retain the multi-head parallel perspective and explain the design motivation of \"subspace division of labor\"",
