  "保留基础量化，同时加入排练日志、观众访谈与案例复盘": "Retain basic quantification while adding rehearsal logs, audience interviews and case reviews",
  "保留旧 encoder-decoder 主干，仅做 attention 微调": "Keep the old encoder-decoder backbone and only do attention fine-tuning",
  "保留局限性，并配套解释你将如何降低不确定性。": "Keep the limitations and explain how you will reduce the uncertainty.",
  "保留可复用部分，但新增关键节点与例外处置清单。": "Retain the reusable parts, but add key nodes and exception handling lists.",
  "保留目标，修正路径": "Keep target, correct path",
  "保留深度 +15%": "Depth of retention +15%",
  "保留缩放步骤，并强调其稳定训练分布的作用": "Keep the scaling step and emphasize its role in stabilizing the training distribution",
  "保守": "keep",
  "保守可讲：多头注意力让模型在不同表示子空间并行关注关系，是结构设计要点；无需声称每个头有固定语义分工。": "It can be conservative: multi-head attention allows the model to pay attention to relationships in different representation subspaces in parallel, which is the key point of structural design; there is no need to claim that each head has a fixed semantic division of labor.",
  "保守实证口径": "Conservative empirical approach",
  "保守延续": "conservative continuation",
  "保守预警": "conservative warning",
  "保守重投入": "Conservative and heavy investment",
  "保住方向，同时降低组织摩擦。": "Maintain direction while reducing tissue friction.",
  "报表好看但信息粗糙，后续很难判断问题出在政策还是执行。": "The report looks good but the information is rough, making it difficult to determine whether the problem lies in policy or execution.",
  "报告编号: #8X92-HAN-DYN • 生成日期: 2023年10月24日": "Report Number: #8X92-HAN-DYN • Date Generated: October 24, 2023",
  "报告编制更费时，却更能支持下一轮决策学习。": "Report preparation is more time-consuming, but it can better support the next round of decision-making and learning.",
  "报告没有耸动结论，却把关键脆弱点放进了正式记录。": "The report did not make sensational conclusions, but it put key vulnerabilities into the official record.",
  "北直隶：推行进度 90%": "Beizhili: Implementation progress 90%",
