  "背景知识：什么是“美丽去杠杆”": "Background knowledge: What is “beautiful deleveraging”",
  "背景知识：为什么要追求 0 → 1": "Background knowledge: Why pursue 0 → 1",
  "背景知识：在人类农业革命中，小麦并不是被动“作物”，它通过高产与可储存性反向塑造了智人的劳动方式、聚落结构和社会组织。": "Background knowledge: In the human agricultural revolution, wheat was not a passive \"crop\". It shaped the working methods, settlement structure and social organization of Homo sapiens through high yield and storability.",
  "被告": "defendant",
  "本案反馈": "Feedback on this case",
  "本单预计收入": "Estimated income for this order",
  "本关卡不声称单一改革能避免所有危机，只强调可验证的改进方向。": "This level does not claim that a single reform can avoid all crises, but only emphasizes verifiable directions for improvement.",
  "本关目标：把研究启发转成低风险、可回滚的政策试点": "The goal of this level: turn research inspiration into low-risk, rollable policy pilots",
  "本关目标：构建透明、可复核的方法路径，处理资料不完整带来的不确定性。": "The goal of this level: to build a transparent and reviewable method path to deal with the uncertainty caused by incomplete data.",
  "本关目标：基于有限证据做扩围、修订或暂停决策": "Objective: Make expansion, revision or suspension decisions based on limited evidence",
  "本关目标：建立“能说什么、不能说什么”的证据边界": "The goal of this level: to establish the evidence boundary of “what can and cannot be said”",
  "本关目标：确定创作方法与排练治理方式，让作品在时间内成形且团队不失速。": "The goal of this level: determine the creative method and rehearsal management method, so that the work can be formed within time and the team will not stall.",
  "本关目标：确定可执行且有学术价值的表演艺术论文题目与问题意识。": "The goal of this level: to determine an executable and academically valuable performing arts thesis topic and problem awareness.",
  "本关目标：让小队形成连贯认知：从单次注意力计算到多头机制，再到位置编码与编码器-解码器整体拼装。": "The goal of this level: Let the team form a coherent cognition: from single attention calculation to multi-head mechanism, to position encoding and the overall assembly of encoder-decoder.",
  "本关目标：完成论文定稿与答辩沟通，确保主张、证据与结论边界一致。": "The goal of this level: Complete thesis finalization and defense communication to ensure that the boundaries of claims, evidence and conclusions are consistent.",
  "本关目标：用保守且可执行的方式，把 src1 结论转成升级路线。": "The goal of this level: Convert the src1 conclusion into an upgrade route in a conservative and executable way.",
  "本关目标：在“时间不站在你这边”的阶段，管理仓位、流动性与沟通风险。": "The goal of this level: manage positions, liquidity and communicate risks during the \"time is not on your side\" stage.",
  "本关目标：在观演体验、可及性与收入压力之间找到平衡，让“到场的人”真正进入作品。": "The goal of this level: to find a balance between viewing experience, accessibility and income pressure, so that \"people present\" can truly enter the work.",
  "本关目标：在利益冲突中维持改革连续性与公共信任": "Objective: Maintain reform continuity and public trust amid conflicts of interest",
  "本关目标：在三次关键节点决策中，确定是否以及如何用 transformer attention mechanism 替换 recurrence，并守住上线秩序。": "The goal of this level: In the three key node decisions, determine whether and how to replace recurrence with transformer attention mechanism, and maintain the online order.",
  "本关目标：在三轮决策中完成架构定案、训练策略与任务扩展路径，平衡稳定(stability)、预算(treasury)、改革(reform)。": "The goal of this level: Complete the finalization of the architecture, training strategy and task expansion path in three rounds of decision-making, balancing stability, budget and reform.",
  "本关目标：在危机后半程平衡短期稳定与长期制度改进。": "The goal of this level: to balance short-term stability and long-term institutional improvement in the second half of the crisis.",
  "本关目标：在压力下完成三次战略选择，验证你是否真正践行“Zero to One”思维。": "The goal of this level: Complete three strategic choices under pressure to verify whether you truly practice \"Zero to One\" thinking.",
  "本关目标：在有限信息中做出可解释的策略选择。": "The goal of this level: make explainable strategic choices with limited information.",
  "本关目标：在有限资金下完成“市场选择—能力建设—商业落地”的连续决策，避免陷入低质量竞争。": "The goal of this level: to complete the continuous decision-making of \"market selection-capacity building-commercial implementation\" with limited funds to avoid falling into low-quality competition.",
  "本关目标：在证据充分但窗口有限的条件下，做出可执行、可复盘的架构与训练决策。": "The goal of this level: Make executable and repeatable architecture and training decisions under conditions with sufficient evidence but limited windows.",
  "本关目标：在主流乐观叙事中，建立自己的风险证据链。": "The goal of this level: to establish your own risk evidence chain in the mainstream optimistic narrative.",
  "本关目标：制定可持续巡演与评估方案，在资金、伦理与长期影响之间完成治理选择。": "The goal of this project: Develop a sustainable tour and evaluation plan, and complete governance choices between funding, ethics and long-term impact.",
