  "从农业到工业再到信息时代，你体验了“系统效率”与“个体幸福”之间持续拉扯。下面是本次小麦模拟器的通关记录。": "From agriculture to industry to the information age, you experience a constant pull between “system efficiency” and “individual happiness.” The following is the clearance record of this wheat simulator.",
  "从轻处置": "lenient treatment",
  "从物种演化的角度看，小麦无疑是赢家；但从个体体验的角度看，许多人却陷入“高产出、低幸福”的生存结构，这就是所谓“奢侈的陷阱”。": "From the perspective of species evolution, wheat is undoubtedly the winner; but from the perspective of individual experience, many people have fallen into a \"high output, low happiness\" survival structure, which is the so-called \"luxury trap.\"",
  "从小市场开始垄断": "Start a monopoly from a small market",
  "促销换增长": "Promotion for growth",
  "存盘并退出模拟": "Save and exit simulation",
  "达到": "achieve",
  "达利欧原则": "Dalio Principle",
  "答辩不是终点，而是让研究从“个人理解”走向“公共可讨论文本”。": "The defense is not the end, but allows the research to move from \"personal understanding\" to \"publicly discussable text\".",
  "答辩厅灯光亮起，评审席前摆着你的论文打印稿，最后一轮抉择开始。": "The lights in the defense hall turn on, a printout of your thesis is placed in front of the review table, and the final round of selection begins.",
  "答辩通过后，你要决定如何公开你的研究成果。": "After passing the defense, you have to decide how to publish your research results.",
  "大航海时代尚未开启，小麦正在蓄力...": "The Age of Discovery has not yet begun, and wheat is gaining strength...",
  "大历史观": "Big view of history",
