  "大明律 · 刑律": "Ming Law·Criminal Law",
  "大学": "University",
  "大约一万年前，小麦开始操纵智人。在农业革命之前，人类过着狩猎采集的生活，虽然未必总是富足，但他们的饮食结构多样，工作时间短，且极少受到传染病的困扰。": "About 10,000 years ago, wheat began to manipulate Homo sapiens. Before the agricultural revolution, humans lived a life of hunter-gatherers. Although they were not always wealthy, they had a diverse diet, short working hours, and were rarely troubled by infectious diseases.",
