  "单调劳动时间": "monotonous labor time",
  "单核框架": "single core framework",
  "单平米净亏损": "Net loss per square meter",
  "单位产出提升后，部落回流耕种，定居网络趋稳。": "After the unit output increased, tribes returned to farming and the settlement network stabilized.",
  "单位面积产量": "Output per unit area",
  "单线防守": "single line defense",
  "单一结果": "single result",
  "单一作物依赖，高密度聚居导致流行病频发。": "Reliance on a single crop and high-density settlements lead to frequent epidemics.",
  "但对于个体人类呢？我们要为小麦清理石块、挑水施肥、弯腰收割。我们的脊椎、膝盖和脚底为此付出了惨痛的代价。我们不仅要忍受身体的病痛，还要时刻担忧干旱和虫灾。我们的人口激增，但大多数人却生活在营养不良和被奴役的边缘。": "But what about individual humans? We have to clear rocks for wheat, carry water and fertilize, and bend down to harvest. Our spines, knees and soles of our feet pay a heavy price. Not only do we have to endure physical pain, but we also have to worry about drought and insect pests all the time. Our population is exploding, but most of us live on the edge of malnutrition and enslavement.",
  "弹性预算": "flexible budget",
  "弹性治理": "Flexible governance",
  "淡化短期风险并追加杠杆，试图尽快扳回账面": "Play down short-term risks and increase leverage, trying to recover the book as soon as possible",
  "当皇权、官僚与财政目标互相冲突时，谁来承担改革成本？": "When imperial power, bureaucracy, and fiscal goals conflict with each other, who bears the cost of reform?",
