  "公开可公开材料，涉及隐私与采购细节走受控查阅，并按议题分场。": "Publicly available materials, including privacy and procurement details, are subject to controlled access and divided into sessions by topic.",
  "公开可缓和流言，但会削弱皇帝议程掌控；密议可保留机动，却会放大“黑箱”质疑。": "Publicity can alleviate rumors, but it will weaken the emperor's control over the agenda; secret discussion can preserve maneuverability, but amplify \"black box\" doubts.",
