  "国本之争进入白热化时，皇帝每天面对的是“短期权威”与“长期合法性”交换。 当时的可做与慎做： - 可做：给出可解释的程序，降低群臣“被排除感”。 - 慎做：反复拖延但不给理由，任由流言扩散。 你接下来三次廷议不是选对错，而是决定冲突如何结算： - 立刻压制，还是分段释放； - 保住裁量，还是换取秩序； - 争当期控制，还是争长期稳定。": "When the dispute over national origins became intense, the emperor was faced with the exchange of \"short-term authority\" and \"long-term legitimacy\" every day. What you can and should do at that time: - What you can do: Provide explainable procedures to reduce the \"feeling of exclusion\" among ministers. - Be careful: procrastinate repeatedly without giving a reason and allow rumors to spread. Your next three court discussions are not about choosing right or wrong, but deciding how to resolve the conflict: - Suppress immediately or release in stages; - Maintain discretion or exchange for order; - Strive for immediate control or long-term stability.",
