  "江南士绅联名罢市，拒绝配合清丈。你的核心任务是让“纸面政令”变成“地方执行”。": "The gentry in the south of the Yangtze River jointly went on strike and refused to cooperate with the Qing Dynasty. Your core task is to turn \"paper decrees\" into \"local executions.\"",
