  "将 recurrence/convolutions 关闭，把 attention 拉到 100%，覆盖双任务，并确保不伪造数据。": "Turn off recurrence/convolutions, raise attention to 100%, cover dual tasks, and ensure that data is not falsified.",
  "将“完成 recurrence 替换”设为发布门槛，正式版以 transformer attention 方案为主": "Set \"Complete recurrence replacement\" as the release threshold, and the official version will focus on the transformer attention solution",
  "将步骤拖拽为“可执行且可核查”路线：先承认旧范式，再落点": "Drag steps into “executable and verifiable” routes: Acknowledge the old paradigm first, then focus on where to start",
  "将访谈作为案例深描，明确“非普遍统计结论”": "Use interviews as case studies to clarify \"non-universal statistical conclusions\"",
  "将概念拖入火堆中心以启动集体想象": "Drag concepts into the center of the fire to kick-start collective imagination",
  "将阶段性发现表述为普遍规律": "Express phased discoveries as universal laws",
  "将题目限定为“某类当代表演中的观演关系建构”": "Limit the title to \"The construction of spectator-performance relationships in certain types of contemporary performances\"",
  "将已有的成功模式扩展到更多地区 (1 → N)。属于水平进步，执行门槛低，但会迅速陷入红海竞争。": "Expand existing successful models to more regions (1 → N). It is a horizontal advancement with low implementation threshold, but it will quickly fall into red ocean competition.",
  "将RNN/CNN作为并列主干混入主讲线，弱化“移除循环与卷积”": "Mix RNN/CNN into the main lecture line as a parallel backbone, weakening the \"removal of loops and convolutions\"",
  "讲解更快，但队员后续容易困惑为何训练会变敏感，概念链条出现断层。": "The explanation is faster, but the team members are likely to be confused later on why the training has become sensitive, and the conceptual chain is broken.",
