  "结算完成：政策组合仍有失衡，去杠杆伴随较高代价。最终指标：社会稳定 ${Math.round(state.social)}%、通胀 ${state.inflation.toFixed(1)}%、债务率 ${Math.round(state.debt)}%。": "Settlement completed: The policy mix is ​​still out of balance, and deleveraging is accompanied by higher costs. Final indicators: social stability ${Math.round(state.social)}%, inflation ${state.inflation.toFixed(1)}%, debt ratio ${Math.round(state.debt)}%.",
