  "批准试点：在核心流量外圈 replacing recurrence，引入 transformer attention mechanism": "Approved for pilot: replacing recurrence in the outer circle of core traffic and introducing transformer attention mechanism",
  "匹配标签会提升兴趣；不匹配会掉兴趣。争议内容会拉高短期兴趣，但明显提高仇恨。广告是主要收入来源。": "Matching tags will increase interest; mismatching will decrease interest. Controversial content will increase short-term interest, but significantly increase hatred. Advertising is the main source of revenue.",
