  "平台会根据评分动态派单。评分越高，单价通常更高，但配送距离更远、时限更短，骑手更容易被迫做高风险操作。": "The platform will dynamically dispatch orders based on ratings. The higher the score, the higher the unit price is usually, but the delivery distance is longer and the time limit is shorter, making it easier for riders to be forced to perform high-risk operations.",
  "平稳": "smooth",
  "评测周只剩一轮训练窗口，你必须在旧范式与新架构之间拍板；每个决定都会改写团队稳定度、经费压力与改革进度。": "There is only one training window left in the evaluation week, and you must make a decision between the old paradigm and the new structure; every decision will rewrite the stability of the team, financial pressure, and reform progress.",
  "评分越高，派单越远、单价越高，时限更短。": "The higher the score, the further the order is dispatched, the higher the unit price, and the shorter the time limit.",
  "评分越高，派单越远、倒计时越短。": "The higher the score, the further the order is dispatched and the shorter the countdown.",
  "评估框架更复杂，但能更真实地反映执行质量和政策效果。": "The evaluation framework is more complex, but can more truly reflect the quality of implementation and policy effects.",
  "评审指出你对来源限制写得过短，建议扩写方法边界。": "The reviewer pointed out that your source restriction was too short and suggested that the method boundary be expanded.",
  "屏幕左下方向键控制转向与前进，右下“冲刺/刹车”控制速度。桌面端也支持 WASD 与方向键。": "The direction keys on the lower left side of the screen control steering and advancement, and the \"sprint/brake\" buttons on the lower right side control speed. Desktop also supports WASD and arrow keys.",
  "瓶颈期": "bottleneck period",
  "迫使人类弯腰收割，造成其脊柱永久性损伤，增加对土地的依赖。": "Forcing humans to bend over to harvest, causing permanent damage to their spines and increasing their dependence on the land.",
  "普里雅·帕特尔": "Priya Patel",
  "七通一平: 道路": "Seven connections and one level: road",
  "七通一平: 水电": "Seven connections and one level: water and electricity",
  "七问": "Seven questions",
  "戚继光之所以能战无不胜，非仅因其勇，更因其能在腐朽的体制缝隙中，寻得一线生机以练强兵。": "The reason why Qi Jiguang was invincible was not only his courage, but also his ability to find a glimmer of hope in the cracks of the corrupt system to train a strong army.",
  "戚家军抗倭要诀： 1) 鸳鸯阵是什么： 由藤牌、狼筅、长枪、刀手、火器分层协同，目标是“先破冲锋，再夺节奏”。 2) 当前 Lv.2 的效果： - 阵型稳定性提升 - 近战协同效率提升 3) 升到 Lv.3 后： - 与鸟铳轮放形成连携 - 对倭寇第一波冲击伤害明显增加 4) 该做与不该做： - 该做：先侦察、再布阵、后接敌。 - 不该做：只堆单点科技，不做协同训练。": "Qi Jiajun's key points for fighting against Japanese invaders: 1) What is the Yuanyang Formation: It consists of rattan cards, wolves, spears, swordsmen, and firearms coordinated in layers. The goal is to \"break the charge first, and then seize the rhythm.\" 2) Effects of the current Lv.2: - Improved formation stability - Improved melee synergy efficiency 3) After upgrading to Lv.3: - Formed a linkage with the cannon rotation - Significantly increased damage to the first wave of Japanese pirates 4) What to do and what not to do: - What to do: Scout first, then set up the formation, and then engage the enemy. - What not to do: Only stack single-point technology and do not do collaborative training.",
  "戚家军总览": "Qi Jiajun Overview",
  "骑手评价": "Rider testimonials",
  "启动小规模跨任务试点，沿用our model配置并设保守成功门槛": "Start a small-scale cross-task pilot, use our model configuration and set a conservative success threshold",
