  "起：${actOptions.qi.find((it) => it.id === state.acts.qi)?.label || \"\"}": "Starting from: ${actOptions.qi.find((it) => it.id === state.acts.qi)?.label || \"\"}",
  "起承转合：${actText}": "From inheritance to transfer: ${actText}",
  "迁徙人群打通了新的商路，小麦有机会进入陌生生态带。": "Migrating people opened up new trade routes, and wheat had the opportunity to enter unfamiliar ecological zones.",
  "迁移初期会带来协作磨合，但方向与来源核心结论一致，有利于后续 quality 与训练效率的系统性提升。": "The early stage of migration will bring collaboration and running-in, but the direction is consistent with the core conclusions of the source, which is conducive to the systematic improvement of subsequent quality and training efficiency.",
