  "切换时间线节点核对证据，再拨动路线开关。要求：路线选择必须与证据一致，且至少复核 5 个节点。": "Switch the timeline node to check the evidence, and then flip the route switch. Requirements: Route selection must be consistent with the evidence and review at least 5 nodes.",
