  "轻便坚韧，防箭矢。": "Lightweight, tough, and arrow-proof.",
  "清查虚报兵额的空饷。此举将得罪地方豪强与同僚。": "Check for empty pay that falsely reports the number of soldiers. This move will offend local powerful officials and colleagues.",
