  "群臣认为国本不定，朝局将长期失焦。若“立长”迟迟不决，礼法秩序会被不断政治化。": "The ministers believe that the country's foundation is uncertain and the government will be out of focus for a long time. If the \"establishment of chiefs\" is delayed, the order of etiquette and law will continue to be politicized.",
  "群臣要求“立长”，你若继续拖延，可保留裁量却会放大政治撕裂。国本之争的实质并非家事，而是皇权与文官体系对“合法性解释权”的争夺。": "The ministers are asking for \"the establishment of a long-term leader.\" If you continue to delay, you can retain your discretion but it will amplify political divisions. The essence of the dispute over the foundation of the country is not a family matter, but a struggle between the imperial power and the civil service system for the \"right to interpret legality.\"",
  "群臣要求公开廷议，透明化国本讨论。公开机制可提升程序合法性，却可能把议题变成舆情战场。": "The ministers demanded that court discussions be made public and national discussions be made transparent. The public mechanism can enhance the legitimacy of the process, but it may turn the issue into a battlefield for public opinion.",
