  "如履薄冰": "walking on thin ice",
  "若强压言官，短期噤声但撕裂加深；若放任争论，威望受损却可能换来更长期合法性。": "If officials are suppressed, their voices will be silenced in the short term but the division will deepen; if debate is allowed, prestige will be damaged but longer-term legitimacy may be gained.",
