  "使用“可能”“倾向于”，并列出仍待验证点": "Use \"maybe\" and \"tend to\" and list points that still need to be verified",
  "世界：场景设定在“神经网络联合指挥部”沙盘室。你手中只有论文摘要信息与个人笔记，需要通过三轮关键决策，组织一次可执行的学习战役方案。": "World: The scene is set in the \"Neural Network Joint Command\" sandbox room. You only have the paper summary information and personal notes in hand, and you need to go through three rounds of key decisions to organize an executable learning campaign plan.",
  "世界：场景位于糖霜港口的自动翻译中枢，旧版链路依赖 recurrence，延迟上升且维护吃紧，团队正在评估 transformer 路线。": "World: The scene is located in the automatic translation center of Sugar Frost Port. The old version of the link relies on recurrence, the delay is rising and the maintenance is tight. The team is evaluating the transformer route.",
  "世界：地点在“联合翻译评测作战室”。背景是序列转导系统长期由复杂循环或卷积编码器-解码器主导，而团队正在评估是否全面切向仅依赖注意力机制的方案。": "World: The location is in the \"Joint Translation Evaluation War Room\". The background is that sequence transduction systems have long been dominated by complex loops or convolutional encoder-decoders, and the team is evaluating whether to fully move towards solutions that rely solely on attention mechanisms.",
  "世界：核心产品依赖 seq2seq 翻译链路，旧系统长期使用 recurrence；你收到唯一高优先级来源 src1，要求据此制定上线路线。": "World: The core product relies on the seq2seq translation link, and the old system has been using recurrence for a long time; you received the only high-priority source src1, requiring you to develop a go-live route accordingly.",
  "世界：近未来城市创业生态，资本谨慎、同质化产品泛滥、用户注意力稀缺。": "World: The urban entrepreneurial ecosystem in the near future is characterized by cautious capital, proliferation of homogeneous products, and scarce user attention.",
  "世界：近未来城市的创业加速营。资源有限、时间紧迫，团队需要在三个关键节点做出方向性决策。": "The World: Entrepreneurship Acceleration Camp in Near Future Cities. With limited resources and tight time, the team needs to make directional decisions at three key nodes.",
  "世界：近未来沿海城市“岚港”，财政紧张、舆论敏感、部门协同薄弱": "World: In the near future, the coastal city \"Langang\" will suffer from financial constraints, sensitive public opinion, and weak departmental coordination.",
  "世界：你在一个高复杂度系统中，必须用有限信息做关键取舍。": "World: You are in a highly complex system and must make key choices with limited information.",
  "世界：时间背景借鉴2005—2008年前后的美国信贷与证券化市场。关卡基于公开常识与广泛报道提炼，不使用未经核实的具体统计。": "World: The temporal background draws on the U.S. credit and securitization market around 2005-2008. The levels are based on public knowledge and extensive reporting, and do not use specific unverified statistics.",
  "世界：时间是季度冲刺前夜。团队长期使用 encoder-decoder 的 recurrent/convolutional 方案，并通过 attention 连接。你收到一份新方案：a new Transformer, based solely on attention。": "World: It’s the eve of the quarter sprint. The team has long used the recurrent/convolutional scheme of encoder-decoder and connected it through attention. You receive a new proposal: a new Transformer, based solely on attention.",
  "世界：学院档案馆、黑盒剧场与答辩厅交错成一条研究战线。当前可参照来源主要是 White Rose ePrint 条目与手动添加网页，公开细节有限。": "World: The college archives, black box theater and defense hall are intertwined into a research front. The current reference sources are mainly White Rose ePrint entries and manually added web pages, with limited public details.",
  "世界：一座正在推进文化更新的沿江城市，三个月后将举行跨场地表演艺术季。你需要与导演、演员、技术团队、场馆方和社区伙伴共同推进项目。": "The World: A city along the river that is promoting cultural renewal will hold a cross-venue performing arts season in three months. You'll work with directors, actors, technical teams, venues and community partners to advance projects.",
