  "土地出让金入库": "Land transfer money deposited into treasury",
  "土地出让收入": "Land transfer income",
  "团队获得共同语言，制作节奏较稳，但部分演员担心真实经验被后置。": "The team has gained a common language and the production rhythm is relatively stable, but some actors are worried that real experience will be postponed.",
  "团队获得统一方向，工程复杂度从“多机制耦合”转向“attention中心化”；短期磨合存在，但改革势能显著提升。": "The team has gained a unified direction, and the engineering complexity has shifted from \"multi-mechanism coupling\" to \"attention centralization\"; short-term running-in exists, but the potential for reform has increased significantly.",
  "团队建议直接采用第三方评级摘要，能节省两周时间并赶上投委会窗口。": "The team recommends directly using the third-party rating summary, which can save two weeks and meet the investment committee window.",
  "团队稳定，但财务缓冲被侵蚀。": "The team is stable, but the financial cushion is eroded.",
  "团队迅速统一方向，变革动能强；但短期磨合压力上升，需要更严密发布节奏。": "The team quickly unified direction and had strong momentum for change; however, the pressure for short-term running-in increased and a stricter release rhythm was required.",
  "推动联合评估协议，明确数据边界、伦理审查和交付节点。": "Promote joint assessment protocols to clarify data boundaries, ethical review and delivery nodes.",
  "推高地价 (Push Land Price)": "Push Land Price",
  "推荐任务": "Recommended tasks",
  "推荐系统会在“留存、广告、情绪刺激”之间做权衡。极化内容能短期拉高停留，但会提升仇恨外部性。": "The recommendation system will make a trade-off between \"retention, advertising, and emotional stimulation.\" Polarizing content can increase retention in the short term, but will increase the externality of hatred.",
  "推进速度较慢，但数据可解释性明显提升。": "Advancement is slower, but data interpretability is significantly improved.",
  "推文池已刷新。": "The tweet pool has been refreshed.",
  "推行受阻": "Implementation blocked",
  "推行顺利": "Implemented smoothly",
  "推演结束后，你将得到一份可直接用于授课的主线：先算注意力，再扩展到多头，最后拼装进完整Transformer框架，并反复强调“保守结论边界”。": "After the deduction, you will get a main line that can be directly used for teaching: first calculate attention, then expand to long positions, and finally assemble it into a complete Transformer framework, and repeatedly emphasize the \"conservative conclusion boundary\".",
  "退出": "quit",
