  "托马斯·谢林": "Thomas Schelling",
  "拖拽或用↑↓调整顺序，目标是从“现状→核心→任务→指标→决议”。": "Drag and drop or use ↑↓ to adjust the order. The goal is to go from \"Current Status→Core→Task→Indicator→Resolution\".",
  "妥协换资源": "Compromise for resources",
  "外部沟通更审慎，避免过度承诺；短期声量一般，但技术信誉与治理纪律更稳。": "External communication is more prudent and avoids over-commitment; the short-term voice is average, but the technical reputation and governance discipline are more stable.",
