  "玩法说明：3 轮随机冲击决策": "Game description: 3 rounds of random impact decisions",
  "玩法说明：你将处理 3 轮随机危机。每次从两种策略里选择其一，系统会实时结算人口、土地、DNA 与生存率变化。": "Gameplay Description: You will deal with 3 rounds of random crises. Each time you choose one of the two strategies, the system will calculate the changes in population, land, DNA and survival rate in real time.",
  "玩法说明：政策组合推演": "How to play: Deduction of policy combinations",
  "万历朝这三件事，分别对应三类风险： 1) 一条鞭法：动的是地方利益分配，不只是税制技术。 可做：先稳征收秩序与执行路径。 慎做：只在诏书层面强推，不管地方承接。 2) 考成法：能拉高短期效率，也会催生“报表达标”。 可做：把考核与真实治理结果绑定。 慎做：只看数字，不看民间反应。 3) 国本之争：表面是立储，实质是合法性解释权。 可做：控制撕裂节奏，避免朝局失控。 慎做：把政治冲突拖成长期对抗。": "These three events during the Wanli Dynasty correspond to three types of risks: 1) One whip: what is affected is the distribution of local interests, not just taxation technology. What can be done: First stabilize the collection order and execution path. Be careful: only push it at the edict level, regardless of local acceptance. 2) Examination method: It can improve short-term efficiency and also give rise to \"reporting standards\". What you can do: Bind the assessment with real governance results. Be careful: only look at the numbers, not the public response. 3) The dispute over national origin: On the surface, it is about establishing a reserve, but in essence, it is about the right to interpret legality. What you can do: Control the tearing rhythm to avoid losing control of the game. Be careful: dragging political conflicts into long-term confrontations.",
  "万历皇帝三轮批红：${decisionSummary}。结果：国库${score.treasury}、秩序${score.order}、改革${score.reform}。请推演后果并给1条策略建议。": "Emperor Wanli approved the red in three rounds: ${decisionSummary}. Result: treasury ${score.treasury}, order ${score.order}, reform ${score.reform}. Please deduce the consequences and give a strategic suggestion.",
  "万历六年 · 春": "Wanli six years · spring",
  "万历六年 · 更新": "Wanli Sixth Year · Updated",
  "万历六年 春 (当前)": "Spring of the sixth year of Wanli (current)",
  "万历六年前后，清丈田亩触碰的是地方士绅和胥吏的既得利益。朝廷诏书可以一夜下达，县乡执行却要穿过宗族关系网。此时最怕的不是公开反对，而是“拖字诀”与“报表作假”。": "Around the sixth year of Wanli, what Qingzhang Tianmu touched was the vested interests of local gentry and subordinate officials. Imperial edicts could be issued overnight, but execution in counties and townships had to go through the clan network. What we fear most at this time is not public opposition, but \"dragging\" and \"falsifying statements.\"",
