  "业绩叙事": "performance narrative",
  "夜色里的联合办公区只剩你工位亮着灯。你手里不是商业计划书，而是一张未被验证的“秘密假设”：也许世界还缺一个真正从0到1的产品。": "In the coworking area at night, only your workstation is lit. What you have in hand is not a business plan, but an unverified \"secret hypothesis\": Maybe the world still lacks a product that can truly go from 0 to 1.",
  "夜色下的饼干王国译站突然拥堵，你接到密令：在不夸大结论的前提下，决定是否让新架构接管跨语种订单。": "The translation station of Biscuit Kingdom is suddenly congested at night, and you receive a secret order: Decide whether to let the new structure take over cross-language orders without exaggerating the conclusion.",
  "夜色中的研究生工位，桌上堆着剧评、演出单与零散笔记，开题会倒计时 48 小时。": "At the graduate student's desk in the dark, there are theater reviews, playbills and scattered notes piled on the table, and there is a 48-hour countdown to the project opening meeting.",
  "一次到位": "Once in place",
