  "一次走台后，演员提出改写关键独白。导演认为会冲击作品统一性。": "After one walk-through, the actor offered to rewrite a key monologue. The director believes that it will affect the unity of the work.",
  "一旦地价下跌，抵押品价值缩水，杠杆将瞬间失衡。你正在推高地价，银行已注意到风险，利息正在悄然上升。": "Once land prices fall and the value of collateral shrinks, leverage will instantly become unbalanced. You're driving up land prices, banks have taken note of the risks, and interest rates are creeping up.",
  "一个索引研究论文和模型权重的专业平台，为机器学习工程师提供比通用搜索好10倍的相关性。": "A specialized platform that indexes research papers and model weights, providing machine learning engineers with 10x better relevancy than general-purpose search.",
  "一家平台型巨头准备复制你的产品功能，并用补贴争夺首批用户。": "A platform giant is ready to copy your product features and use subsidies to compete for the first users.",
