  "已知结论指向：new transformer是based on attention，且在translation任务上show更优质量与并行潜力；但迁移成本需管理。": "Known conclusions point to: the new transformer is based on attention, and shows better quality and parallel potential on translation tasks; but the migration cost needs to be managed.",
  "已知文本show：transformer在英语成分句法分析上可行，且在large/limited training data下都有结果；但范围外结论应谨慎。": "Known text show: transformer is feasible in syntactic analysis of English components, and has results under large/limited training data; however, conclusions outside the scope should be cautious.",
  "以 Airbnb 为例：主流意见认为“陌生人不会互相信任”，但其通过评价体系与担保机制，把“不可能的交易”变成了规模化市场。": "Take Airbnb as an example: the mainstream opinion is that \"strangers will not trust each other\", but through its evaluation system and guarantee mechanism, it has turned \"impossible transactions\" into a large-scale market.",
