  "优先处理会影响“生存率”和“传播面积”的危机事件，避免一次失误导致区域大规模流失。": "Prioritize handling of crisis events that will affect \"survival rate\" and \"spread area\" to avoid a single mistake leading to large-scale regional loss.",
