  "御案提示：优先观察“秩序”与“改革”的此消彼长。": "Imperial Notice: Prioritize observing the ebb and flow of \"order\" and \"reform\".",
  "御批“${label}”已下：国库 ${formatDelta(opt.impact.treasury)} / 秩序 ${formatDelta(opt.impact.order)} / 改革 ${formatDelta(opt.impact.reform)}": "The imperial approval \"${label}\" has been issued: Treasury ${formatDelta(opt.impact.treasury)} / Order ${formatDelta(opt.impact.order)} / Reform ${formatDelta(opt.impact.reform)}",
  "御史刘台弹劾首辅“专权乱政，动摇国本”，奏折已递入司礼监。若不处理，官场名声将大幅下降。": "Censor Liu Tai impeached the chief minister for \"authoritarianism and chaos in government, shaking the foundation of the country\", and the memorial has been handed over to the Supervisor of Ceremonies. If it is not dealt with, the reputation of the officialdom will be greatly reduced.",
  "鸳鸯阵": "Yuanyang formation",
  "鸳鸯阵 Hover 提示": "Yuanyang Formation Hover Tips",
