  "鸳鸯阵 Lv.3（-800两）": "Yuanyang Formation Lv.3 (-800 Liang)",
  "鸳鸯阵不是单一武器，而是协同战术系统。 Lv.2：可稳定接敌，减少阵型崩溃。 Lv.3：加入鸟铳轮放与哨探情报，形成“火器压制 + 近战收割”的完整闭环。": "The Yuanyang Formation is not a single weapon, but a collaborative tactical system. Lv.2: Can stably engage the enemy and reduce formation collapse. Lv.3: Add the rotation of bird cannons and sentinel intelligence to form a complete closed loop of \"firearm suppression + melee harvesting\".",
