  "跃迁点": "transition point",
  "运营更复杂，却提升公共性与讨论空间。": "The operation is more complex, but it improves publicity and discussion space.",
  "运营数据看板": "Operational data dashboard",
  "运营压力暂时较小，但增长波动变大，商业化节奏受外部环境影响，战略主动权下降。": "Operational pressure is temporarily small, but growth fluctuations have become greater, the pace of commercialization is affected by the external environment, and strategic initiative has declined.",
  "灾年赈粮流失，牵涉胥吏与仓官。": "The loss of food relief in disaster years involves subordinate staff and warehouse officials.",
  "再开一局": "Another round",
  "在 3 轮冲击中兼顾社会稳定、通胀风险和债务路径。": "Balancing social stability, inflation risks, and debt paths across 3 waves of shocks.",
  "在“全球化复制”带来的水平进步与“科技创新”带来的垂直进步之间做出抉择。只有打破现状的新技术，才能带领文明跨越奇点。": "Make a choice between horizontal progress brought about by \"global replication\" and vertical progress brought about by \"technological innovation.\" Only new technologies that break the status quo can lead civilization beyond the singularity.",
  "在别的 App 看开箱视频": "Watch unboxing videos on other apps",
  "在不确定环境里，尽量提高“壁垒 + 确定性”的组合质量。": "In an uncertain environment, try to improve the quality of the combination of \"barriers + certainty\".",
  "在不确定环境中，可先锁定基本盘，再保留实验窗口，避免单一路径风险。": "In an uncertain environment, you can lock the basic disk first and then retain the experimental window to avoid the risk of a single path.",
  "在当前信息条件下，你如何落地“replacing recurrence”这一步？": "Under the current information conditions, how do you take the step of \"replacing recurrence\"?",
  "在当时政治语境里，争议并不只看政策本身，而看是否符合礼制叙事。张居正每推进一步，都要同步回答“你是否僭越祖制”。因此改革常常要付出额外政治成本。": "In the political context at that time, the controversy was not just about the policy itself, but whether it conformed to the ritual narrative. Every time Zhang Juzheng takes a step further, he must simultaneously answer \"Are you violating the ancestral system?\" Reforms therefore often come with additional political costs.",
  "在非高峰时段完成 50 次深度阅读": "Complete 50 in-depth reads during off-peak hours",
  "在复杂信用产品里，底层借款人质量与再融资能力是风险起点。": "In complex credit products, the quality and refinancing ability of the underlying borrower are the starting point of risk.",
  "在高情绪环境下，承认不确定性并给出可执行建议更有长期价值。": "In high-emotion environments, acknowledging uncertainty and making actionable recommendations has greater long-term value.",
  "在减少债务规模的同时，通过政策组合避免经济出现剧烈收缩，实现债务/收入比率的良性下降。": "While reducing the scale of debt, we should avoid a sharp economic contraction through a combination of policies and achieve a healthy decline in the debt/income ratio.",
  "在缺乏充分模型与数据时，给精确概率可能造成伪确定性。": "In the absence of sufficient models and data, giving precise probabilities may result in false certainty.",
  "在缺乏统一行业基准时，混合评估更稳妥：基础量化+过程叙事+样本访谈。": "In the absence of unified industry benchmarks, a hybrid assessment is more reliable: basic quantification + process narrative + sample interviews.",
  "在缺少精确预测时，可采用“主票价+有限配额”以兼顾可控与可达。": "In the absence of accurate predictions, \"main fare + limited quota\" can be used to balance controllability and accessibility.",
  "在任意模拟器中完成并退出一次阅读流程": "Complete and exit a reading process in any simulator",
  "在试点阶段保留小比例机动资金，可降低执行中断概率。": "Retaining a small proportion of mobile funds during the pilot phase can reduce the probability of execution interruption.",
  "在狩猎采集时代，多数人每日劳动时间更短，饮食来源更多样，身体承受的重复性损伤也更少。进入农业社会后，人类为了保障单一作物，必须投入更长劳动时间，承担更高风险。": "In the age of hunter-gatherers, most people worked shorter hours each day, ate from more diverse sources, and suffered less repetitive injuries to their bodies. After entering an agricultural society, humans must invest longer working hours and bear higher risks in order to secure a single crop.",
  "在四个生活战场中都完成至少一本书。": "Complete at least one book in each of the four living battlegrounds.",
  "在危机中平衡生存率与扩张速度，观察农业系统如何反向“驯化”人类。": "Balance survival rate and expansion speed in a crisis, and observe how the agricultural system \"domesticates\" humans in reverse.",
  "在现有市场中竞争，改进现有产品。这是 1 到 n 的陷阱。": "Compete in existing markets and improve existing products. This is a 1 to n trap.",
  "在线学友": "Online Alumni",
  "在信息不完备时，可用“条件性预警”替代“绝对断言”。": "When the information is incomplete, \"conditional warning\" can be used instead of \"absolute assertion\".",
  "在这片充满\"常识\"的红海中，有一个被大多数人忽视的观点正在闪烁。": "In this red sea of ​​\"common sense\", there is a point of view that is ignored by most people.",
  "在证据不完整时，应区分“研究提示”与“政策结论”。": "When the evidence is incomplete, a distinction should be made between “research tips” and “policy conclusions.”",
  "在证据不足处标注不确定性，是学术诚信的一部分。": "Noting uncertainty where the evidence is weak is part of academic integrity.",
  "在证据外推有限时，分层抽样或分区推进更有利于识别真实效果。": "When extrapolation of evidence is limited, stratified sampling or zone boosting is more beneficial in identifying true effects.",
  "在证据有限时，最稳妥的专业动作是紧扣来源原句推进方向决策，同时避免杜撰量化承诺。": "When the evidence is limited, the safest professional action is to stick closely to the original sentence of the source to make direction decisions, while avoiding fabricating quantitative promises.",
  "暂缓替换：维持 recurrence 主链路，仅做离线评估": "Suspend replacement: maintain the recurrence main link and only perform offline evaluation",
