  "战果：戚家军成功击退倭寇，沿海防线稳住。": "Result: The Qi Army successfully repelled the Japanese pirates and the coastal defense line was stabilized.",
  "战果：首轮交战未能完全压制倭寇，需要继续补齐科技协同。": "Result: The first round of fighting failed to completely suppress the Japanese pirates, and technological coordination needs to be continued.",
