  "战术评级：方案可执行，仍需收紧参数": "Tactical rating: The plan is executable, but parameters still need to be tightened",
  "战役方案形成闭环：从算子到系统层次一致，且严格贴合现有证据范围。": "The campaign plan forms a closed loop: it is consistent from operator to system level and strictly fits the scope of existing evidence.",
  "张居正": "Zhang Juzheng",
  "张居正调度面板": "Zhang Juzheng scheduling panel",
  "张居正画像": "Portrait of Zhang Juzheng",
  "张居正请求折银并役，换取财政与征收效率。表面上这是税制技术升级，实则是在重排“谁交税、谁获利、谁承担改革成本”。豪强利益受损后，地方执行很可能出现隐性抵抗。": "Zhang Juzheng requested to exchange silver and join the army in exchange for financial and collection efficiency. On the surface, this is a technical upgrade of the tax system, but in fact it is a rearrangement of \"who pays taxes, who profits, and who bears the cost of reform.\" After the powerful interests are damaged, there is likely to be implicit resistance in local enforcement.",
  "张居正三轮调度：${decisionSummary}。结果：执行${score.exec} 阻力${score.resistance} 合法性${score.legitimacy} 太仓银${silver} 支持度${support}。请给结构后果与1条建议。": "Zhang Juzheng’s three rounds of scheduling: ${decisionSummary}. Result: Execution ${score.exec} resistance ${score.resistance} legitimacy ${score.legitimacy} Taicangyin ${silver} support ${support}. Please give structural consequences and 1 suggestion.",
  "章节导览 · 金钱宗教": "Chapter Navigation · Money Religion",
  "章节导览 · 面对空白": "Chapter Navigation · Facing the Blank",
  "长期高强度农作导致部分部落回归采集，定居秩序出现波动。": "Long-term high-intensity farming has caused some tribes to return to gathering, and the settlement order has fluctuated.",
  "长期里程碑": "long term milestones",
  "长期稳定性更高，但短期阻力会增加。": "Long-term stability is greater, but short-term resistance will increase.",
  "长枪方阵": "Phalanx of Lances",
  "长枪线在狼筅之后补位，是戚家军近战主杀伤层。": "The spear line takes up the position behind Langzhen and is the main killing layer of Qi Jiajun's close combat.",
  "账面潜在收益更高，同时暴露于流动性与执行断裂风险。": "Potential returns on paper are higher while being exposed to liquidity and execution disruption risks.",
  "账面整齐，但基层会把风险转嫁为隐性减配。": "The books are neat, but the grassroots will pass on the risks as hidden allocation reductions.",
  "召开廷议": "convene a court meeting",
  "折办银两纳贡": "Redeem silver to pay tribute",
  "折损麦秆": "Broken wheat straw",
  "这 5 条“真相”被故意掩盖？": "Were these 5 “truths” deliberately concealed?",
  "这本书讨论的不是“如何在已有赛道里跑得更快”，而是“如何创造一个以前不存在的新价值”。": "This book is not about \"how to run faster on an existing track\", but \"how to create a new value that did not exist before.\"",
  "这关训练的是在信息不完整条件下做权衡。": "This level of training is about making trade-offs under conditions of incomplete information.",
  "这里什么都没有，直到我们亲眼所见。": "There is nothing here until we see it with our own eyes.",
  "这幕核心问题来自《从0到1》：复制成熟模式是 1→N，创造不可替代能力是 0→1。你要在增长速度、现金压力与护城河之间做取舍。": "The core issue in this scene comes from \"From 0 to 1\": copying the mature model is 1→N, and creating irreplaceable capabilities is 0→1. You have to choose between growth rate, cash pressure and moat.",
  "这是《万历十五年》中最典型的结构冲突：在乡绅网络主导的基层社会里，法律条文与实际权力并不重合。海瑞若严格执法，会触发官场连锁排挤；若网开一面，则法治公信迅速坍塌。": "This is the most typical structural conflict in \"The Fifteenth Year of Wanli\": in the grassroots society dominated by the squire network, legal provisions and actual power do not coincide. If Hai Rui strictly enforces the law, it will trigger a chain of squeezes in the officialdom; if the rule of law is open to one side, public trust in the rule of law will quickly collapse.",
  "这是虚构力量的终极物化展现。若没有共同的宗教信仰，成千上万的劳动力绝无可能在没有血缘关系的情况下进行长达数年的紧密协作。": "This is the ultimate materialized display of the power of fiction. Without a common religious belief, it would be impossible for thousands of workers to work closely together for several years without blood ties.",
  "这是一个创造生产力的“良性债务”，还是会导致泡沫的“恶性债务”？": "Is this a “good debt” that creates productivity, or a “bad debt” that leads to bubbles?",
  "这种为了“未来更多的人口”而牺牲“当下个体幸福”的模式，就是历史上最大的奢侈陷阱。一旦习惯了奢侈的生活（例如稳定的食物来源），就再也回不去了，哪怕代价是终身劳碌。": "This model of sacrificing \"current individual happiness\" for \"more population in the future\" is the biggest luxury trap in history. Once you get used to the luxuries of life (such as a steady source of food), you can never go back, even if it comes at the cost of a lifetime of toil.",
