  "主题：${theme?.label || \"\"}": "Theme: ${theme?.label || \"\"}",
  "主线任务：基于 src1 的结论，设计并推进以 transformer attention mechanism 为核心的替换方案，在不夸大证据的前提下争取 translation quality 的提升。": "Main task: Based on the conclusions of src1, design and promote a replacement solution with the transformer attention mechanism as the core, and strive to improve translation quality without exaggerating the evidence.",
  "主线任务：基于已知证据完成三次关键抉择：架构取舍、训练部署、任务扩展，目标是在可控风险内争取质量与效率的双重领先。": "Main task: Complete three key decisions based on known evidence: architecture selection, training deployment, and task expansion. The goal is to strive for dual leadership in quality and efficiency within controllable risks.",
  "主线任务：通过连续场景推演，把知识点转化为可执行判断。": "Main task: transform knowledge points into executable judgments through continuous scenario deduction.",
  "主线任务：通过三幕决策，完成“识别风险—执行策略—参与复盘”的闭环，在收益、稳定与改革之间取得可辩护的平衡。": "The main task: through three acts of decision-making, complete the closed loop of \"identifying risks - executing strategies - participating in review\", and achieve a defensible balance between returns, stability and reform.",
  "主线任务：依据 src1 的核心结论，设计三步决策：是否以 attention mechanism replacing recurrence，推动 seq2seq translation quality 的稳健改进，并平衡稳定、财政与改革节奏。": "Main task: Based on the core conclusions of src1, design a three-step decision: whether to replace recurrence with attention mechanism, promote the steady improvement of seq2seq translation quality, and balance stability, finance and reform rhythm.",
  "主线任务：用三个回合完成一次“Zero to One”战略试炼：找到独特价值、构建分销路径、形成可持续优势。": "Main mission: Complete a \"Zero to One\" strategy trial in three rounds: find unique value, build distribution paths, and form sustainable advantages.",
  "主线任务：在不夸大论文结论的前提下，构建一条从注意力计算到整体架构的学习路径，让小队理解Transformer为何能在设计上摆脱循环与卷积。": "Main task: Without exaggerating the conclusion of the paper, build a learning path from attention calculation to the overall architecture, so that the team can understand why Transformer can get rid of loops and convolutions in design.",
  "主线任务：在不伪造具体统计、不夸大证据的前提下，完成选题、方法与写作三阶段推进，交付一篇论证清晰、边界明确的表演艺术论文。": "The main task: without falsifying specific statistics or exaggerating evidence, complete the three stages of topic selection, method and writing, and deliver a performing arts paper with clear arguments and clear boundaries.",
  "主线任务：在不虚构数据的前提下，依据已知结论推动架构决策：是否从旧范式迁移到 Transformer，并在 translation 与其他 tasks 上制定推进节奏。": "Main task: Promote architectural decisions based on known conclusions without fabricating data: whether to migrate from the old paradigm to Transformer, and establish a progression rhythm for translation and other tasks.",
  "主线任务：在三次关键抉择中，验证“从0到1”路径：找到独特价值、构建不可替代性、把价值有效交付给市场。": "Main task: Verify the \"from 0 to 1\" path in three key decisions: find unique value, build irreplaceability, and effectively deliver value to the market.",
  "主线任务：在三幕决策中，维持项目稳定、守住预算、推动有意义的创作与制度改进，让演出不仅“上演”，还“被理解、被参与、可持续”。": "Main mission: In the three-act decision-making process, maintain project stability, stick to the budget, and promote meaningful creation and system improvements, so that the performance is not only \"performed\" but also \"understood, participated in, and sustainable.\"",
  "主线任务：在无法完整掌握原文细节的前提下，基于公开常识和谨慎推断，把研究线索转化为一套低风险、可评估、可迭代的政策试点。": "The main task: Without fully grasping the details of the original text, based on open common sense and careful inference, transform research clues into a set of low-risk, evaluable, and iterable policy pilots.",
  "主线替换": "Mainline replacement",
  "主演：${lead?.name || \"\"}（${(lead?.tags || []).join(\"/\")}）": "Starring: ${lead?.name || \"\"}（${(lead?.tags || []).join(\"/\")}）",
