  "主预算之外争取小比例应急池，并绑定触发条件与审批路径。": "Strive for a small proportion of the emergency pool in addition to the main budget, and bind trigger conditions and approval paths.",
  "主张以市场自我修复为主，延后硬性约束": "Advocates focusing on market self-repair and postponing hard restrictions",
