  "主张B：WMT 2014 English-to-French 单模型 41.8 BLEU，训练 3.5 days on eight GPUs，training cost 是 best models 的 small fraction。": "Claim B: WMT 2014 English-to-French single model 41.8 BLEU, training 3.5 days on eight GPUs, training cost is a small fraction of the best models.",
