  "slider.closest(\".group\")).filter(Boolean); const levelEls = sliderBlocks.map((block) => block.querySelector(\"span.font-mono.font-bold\")); const remainingEl = Array.from(document.querySelectorAll(\"aside .ink-panel span\")).find((el) => (el.textContent || \"\").includes(\"剩余点数\")); const executeBtn = Array.from(document.querySelectorAll(\"button\")).find((btn) => (btn.textContent || \"\").includes(\"执行本月政令\")); const archiveBtn = Array.from(document.querySelectorAll(\"button\")).find((btn) => (btn.textContent || \"\").includes(\"查阅《实录》档案\")); if (!executeBtn) return; executeBtn.innerHTML = '": "slider.closest(\".group\")).filter(Boolean); const levelEls = sliderBlocks.map((block) => block.querySelector(\"span.font-mono.font-bold\")); const remainingEl = Array.from(document.querySelectorAll(\"aside .ink-panel span\")).find((el) => (el.textContent || \"\").includes(\"Remaining points\")); const executeBtn = Array.from(document.querySelectorAll(\"button\")).find((btn) => (btn.textContent || \"\").includes(\"Execute this month's decree\")); const archiveBtn = Array.from(document.querySelectorAll(\"button\")).find((btn) => (btn.textContent || \"\").includes(\"Check the \"Record\" file\")); if (!executeBtn) return; executeBtn.innerHTML = '",
  "src1 的核心逻辑是 transformer attention mechanism 通过 replacing recurrence 改善 seq2seq translation quality。": "The core logic of src1 is the transformer attention mechanism to improve seq2seq translation quality through replacing recurrence.",
  "src1 仅说明 improves seq2seq translation quality 的方向，未给出精确增益，决策应保守表述。": "src1 only illustrates the direction that improves seq2seq translation quality. The precise gain is not given, and the decision should be stated conservatively.",
  "src1 支持替换方向，但未定义所有边界场景；分层切换与回退预案更符合保守原则。": "src1 supports replacement directions, but does not define all boundary scenarios; the hierarchical switching and fallback plan is more in line with conservative principles.",
  "src1 只提供方向结论：replacing recurrence 与 improves seq2seq translation quality 同时出现；未提供精确收益值。": "src1 only provides directional conclusions: replicating recurrence and improving seq2seq translation quality occur simultaneously; no precise benefit value is provided.",
