  "Zero to One 的核心不是喊口号，而是在关键时刻选择“创造独特性”并为之配置资源。": "The core of Zero to One is not to shout slogans, but to choose to \"create uniqueness\" and allocate resources for it at critical moments.",
  "Zero to One 强调“差异化创造”而非“高效率模仿”。先定义独特价值，再谈规模复制。": "Zero to One emphasizes \"differentiated creation\" rather than \"highly efficient imitation\". Define unique value first, then talk about replicating at scale.",
